parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "intent": {
      "type": "string",
      "enum": ["stock", "faq", "complaint", "none"],
      "description": "stock — наличие/остаток/количество товара; faq — доставка, оплата, оформление, самовывоз, возврат; none — всё остальное"
    },
    "confidence": {
      "type": "string",
      "enum": ["high", "mid", "low"]
    },
    "lang": {
      "type": "string",
      "description": "Язык обращения клиента — код ISO 639-1 из двух букв в нижнем регистре: ru, uk, de, en, pl, tr и т.д. Определять по самому тексту, а не по алфавиту: украинский и русский пишутся кириллицей, но это разные языки"
    },
    "query_norm": {
      "type": "string",
      "description": "Короткая нормализованная формулировка запроса по-русски"
    },
    "slots": {
      "type": "object",
      "properties": {
        "product": { "type": "string" },
        "variant": { "type": "string" },
        "color": { "type": "string" }
      },
      "description": "Заполнять только тем, что прямо сказано клиентом, по-русски. Не догадываться."
    }
  },
  "required": ["intent", "confidence", "lang"]
}

parameters.jsCode:
// Нормализация вывода классификатора + запасной путь по ключевым словам (план §5.3).
//
// Почему fallback здесь, а не отдельной нодой на error-выходе:
// при ошибке под-ноды (парсера) цепочка отдаёт элемент в ОСНОВНОЙ выход,
// а не в error-выход — проверено на прогонах 840/841.
const raw = $input.first().json;
const out = raw.output || raw;

// Что сказал клиент: из своего входа (у ошибочного элемента это поле text), иначе ссылкой на STT
let sourceText = String(raw.source_text || out.source_text || raw.text || '');
// Транскрипт приходит либо от локального STT, либо от облачного запасного —
// спрашиваем оба по очереди. Ссылка на одну ноду ломается при свапе движка:
// неработающая сквозная ссылка отдаёт пустоту без ошибки (прогон 917).
if (!sourceText) {
  for (const n of ['5c. STT — whisper.cpp (локально, Tailscale)', '5. STT — Whisper (auto)  [SWAP→LOCAL]']) {
    try {
      const t = String($(n).first().json.text || '');
      if (t) { sourceText = t; break; }
    } catch (e) {}
  }
}

let intent = String(out.intent || '').toLowerCase().trim();
let conf = String(out.confidence || '').toLowerCase().trim();
let fallback = false;

if (!['stock', 'faq', 'complaint', 'none'].includes(intent)) {
  // Классификатор не дал пригодного ответа — грубая подстраховка по ключевым словам.
  const t = sourceText.toLowerCase();
  const has = (words) => words.some(w => t.includes(w));

  // Три языка обслуживания — значит и запасной путь должен знать все три.
  // Без украинских слов этот рубеж был для украинского слеп: при отказе классификатора
  // законный вопрос про товар уходил в оффтоп (прогон 882).
  const COMPLAINT = ['жалоб', 'жаловат', 'недовольн', 'возмущ', 'претензи', 'верните деньги',
                    'жаліт', 'скарг',
                    'beschwerde', 'beschweren', 'unzufrieden', 'reklamation'];
  const STOCK = ['сколько', 'есть ли', 'в наличии', 'наличи', 'остат', 'склад',
                 'чи є', 'наявн', 'залиш', 'скільки',
                 'verfügbar', 'vorrätig', 'bestand', 'lager', 'wie viele'];
  const FAQ = ['доставк', 'оплат', 'оплач', 'самовывоз', 'забрать', 'возврат', 'счёт', 'счет',
               'самовивіз', 'поверненн', 'рахунок', 'забрати', 'терміни',
               'lieferbeding', 'lieferung', 'liefer', 'versand', 'zahlung', 'bezahl',
               'abholung', 'abholen', 'rückgabe', 'rechnung'];

  intent = has(COMPLAINT) ? 'complaint' : (has(STOCK) ? 'stock' : (has(FAQ) ? 'faq' : 'none'));
  conf = 'low';
  fallback = true;
}

if (!['high', 'mid', 'low'].includes(conf)) conf = 'low';

// Язык обращения определяет модель (код ISO 639-1), а не алфавит
let lang = String(out.lang || '').toLowerCase().trim().slice(0, 2);
if (!/^[a-z]{2}$/.test(lang)) lang = '';

// --- КОНТЕКСТ ДИАЛОГА (14.08.2026) ------------------------------------------
// Почему ведём его САМИ, а не под-нодой памяти:
// подключённая memoryBufferWindow до цепочки НЕ ДОЕЗЖАЕТ: валидация её принимает,
// ошибок нет, эффекта ноль — три реплики подряд (прогоны 1004→1005→1006) классификатор
// каждый раз начинал с чистого листа. Замер моделей показал, что с историей справляется
// даже текущая 12B — значит дело не в модели, а в доставке контекста.
// Здесь он детерминирован, виден в данных прогона и не зависит от под-нод.
const CTX_TTL_MIN = 30;   // старше — это уже новый разговор, наследовать нельзя

let chatId = 'unknown';
try { chatId = String($('1. Telegram Trigger (voice)').first().json.message.chat.id || 'unknown'); } catch (e) {}

const slots = out.slots || {};
let product = String(slots.product || '').trim();
let queryNorm = String(out.query_norm || sourceText);
let inherited = false;

// Разговорные синонимы объёма (15.08.2026, разбор прогона 1411): клиент говорит «компакт»/«побольше»,
// а не литрами — литеральной цифры в тексте нет, поэтому обычный цифровой матчинг (ниже) не сработает.
// Ключевое слово «компакт» буквально совпадает с пометкой в названии каталога (1.0л (компакт)) —
// используем это же слово как разговорный маркер объёма.
const VARIANT_SYNONYMS = [
  { re: /компакт|мини(?!атюр)|маленьк/i, variant: '1.0' },
  { re: /семейн|вместительн|больш(ой|ая|е|им)/i, variant: '1.7' },
];
let colloquialVariant = '';
for (const { re, variant } of VARIANT_SYNONYMS) {
  if (re.test(sourceText)) { colloquialVariant = variant; break; }
}

// Анафоры-обобщения («товар», «их», «this», «es»…) — это отсутствие продукта, а не сам продукт.
// Повод (прогон 1030): «Вы уверены, что у вас их 113 штук?» → product: "товар" →
// наследование не срабатывало, потому что product был НЕПУСТОЙ. Само обобщённое слово —
// уже маркер продолжения, отдельного совпадения с FOLLOWUP не требуем.
const GENERIC = ['товар', 'товары', 'это', 'этот', 'они', 'их', 'он', 'она', 'оно',
                  'це', 'він', 'вона', 'воно',
                  'produkt', 'artikel', 'ware', 'es', 'sie', 'dieser'];
const productIsGeneric = GENERIC.includes(product.toLowerCase());
if (productIsGeneric) product = '';

// Маркеры продолжения разговора на трёх языках обслуживания.
// Без них наследовать нельзя: «расскажите анекдот» после вопроса о чайниках
// не должно превращаться в вопрос о чайниках.
const FOLLOWUP = /какие|какой|вариант|подешевле|подороже|а есть|еще|ещё|другой|другие|мне нужен|мне нужна|возьму|давайте|які|який|варіант|ще|інший|welche|welcher|andere|billiger|günstiger|noch/i;

// Голое подтверждение («да», «хорошо», «ок») отвечает на вопрос АССИСТЕНТА (обычно —
// его же приглашение оформить заказ), а не открывает новую тему. Без этого маркера
// intent уходил в 'none' и разговор ломался прямо на закрытии сделки
// (прогон 1055: «Да, мне будет удобно» после «Вам удобно оформить заказ?» → оффтоп-отказ).
// \b в JS-regex опирается на \w = [A-Za-z0-9_] и кириллицу вообще не видит — с ним «да\b» никогда не
// срабатывает на русском тексте (проверено node -e при внедрении). Граница слова —
// отрицательный lookahead на следующую букву, включая кириллицу.
// Whisper на односложном звуке гадает и язык, и письмо: прогон 1102 — голосовое «Да.»
// пришло как «- Da.» латиницей с lang: pl → маркер ждал кириллицу и начало строки,
// не совпал — сделка сорвалась оффтоп-отказом на немецком. Поэтому: (1) ведущая
// пунктуация срезается, (2) латинские подтверждения принимаются, но «da» — ТОЛЬКО
// одиночным словом: в немецком «Da bin ich nicht sicher» начинается с «Da»,
// и длинная фраза с него — не согласие.
const confirmProbe = sourceText.trim().replace(/^[\s\-–—.,!?…]+/, '');
// E8/А2 (14.08, разбор прогона 1139): два уровня. STRONG — однозначные слова
// согласия, срабатывают начало фразы, как и раньше. WEAK — вводные/многозначные
// слова («так», «хорошо», «ok»…) считаются подтверждением ТОЛЬКО если они — ВСЯ реплика
// (≤ 2 слова), иначе ложно срабатывают вводное слово в начале вопроса (прогон 1139: «Так, от
// какой суммы доставка бесплатна?» — intent faq правильный, но CONFIRM ложно сработал на «так»).
const STRONG_CONFIRM = /^(да|ага|угу|согласен|согласна|згоден|згодна|подтверждаю|оформляйте|ja|yes)(?![а-яёіїєa-z])/i;
const WEAK_CONFIRM = /^(так|хорошо|ок|окей|добре|гаразд|da|ok|okay|gut|einverstanden|passt)[\s.!?…]*$/i;
const confirmWordCount = confirmProbe.split(/\s+/).filter(Boolean).length;
const isWeakConfirm = confirmWordCount <= 2 && WEAK_CONFIRM.test(confirmProbe);
// Гварды: вопросительная реплика, intent faq или «да нет» вместе — не подтверждение.
// \b опирается на \w = [A-Za-z0-9_] и кириллицу не видит (та же грабля, что и в CONFIRM выше) —
// границы слова через lookahead/lookbehind, проверено node -e на «Да нет, не надо» до применения.
const hasQuestionMark = sourceText.includes('?');
const hasDaWord = /(?<![а-яёіїєa-z])да(?![а-яёіїєa-z])/i.test(sourceText);
const hasNetWord = /(?<![а-яёіїєa-z])нет(?![а-яёіїєa-z])/i.test(sourceText);
const generalGuardBlocked = hasQuestionMark || (hasDaWord && hasNetWord);
const confirmGuardBlocked = intent === 'faq' || generalGuardBlocked;
const isConfirm = !confirmGuardBlocked && (STRONG_CONFIRM.test(confirmProbe) || isWeakConfirm);
// E9-CONFIRM-фикс (разбор серии 1208–1236): естественные фразы подтверждения типа
// «Давайте оформим, да» / «Оформим.» / «Белый чайник хочу заказать» не ловились
// STRONG/WEAK выше и часто классифицировались как faq/none (сам промпт классификатора относит
// «оформление» к faq) — в бою А2 давал 5 промахов подряд, прежде чем Dennis случайно попал
// в голое «Да.», которое распознаётся. По решению оркестратора: ORDER_CONFIRM обходит faq-гвард
// (он бессмыслен именно вне контекста подтверждения), но НЕ обходит вопросительный/«да нет»
// гварды («Как оформить заказ?» — это вопрос, не подтверждение) и применяется только
// внутри orderConfirmed (ниже) — там уже есть гвоздь prev.awaitingConfirm, вне этого окна те же
// слова могут быть обычным FAQ-вопросом про оформление.
const ORDER_CONFIRM = /(оформ|заказат|заказыва|бер[уё]|возьм|покупа|купит|bestell|kaufen|nehme)/i;
const orderIntentConfirm = !generalGuardBlocked && ORDER_CONFIRM.test(sourceText);

const store = $getWorkflowStaticData('global');
store.dialogCtx = store.dialogCtx || {};
const prev = store.dialogCtx[chatId];
const fresh = prev && prev.product && (Date.now() - (prev.ts || 0)) < CTX_TTL_MIN * 60000;

// Язык односложной реплики — из контекста разговора, не из мгновенной детекции:
// одно слово не меняет язык разговора (прогон 1102: «Да.» → pl/de → ответ немецким).
const isShortUtterance = confirmProbe.split(/\s+/).filter(Boolean).length <= 1;
// Фикс 18.08 (прогон 1846): хотфикс выше был слишком широким — он гасил ЛЮБУЮ смену
// языка на короткой реплике, и русское «Увидимся.» в украинском контексте получало
// ответ по-украински. Подмену из контекста оставляем ТОЛЬКО для заведомо неоднозначных
// междометий согласия/отказа/отмены: у них нет собственных языковых признаков, и именно
// на них whisper гадает язык (прогон 1102: «Да.» → pl). Слово со своей морфологией
// («Увидимся», «Дякую», «Danke») язык разговора определяет само — доверяем детекции STT.
const AMBIGUOUS_SHORT = /^(да|ага|угу|так|хорошо|ок|окей|добре|гаразд|згоден|згодна|согласен|согласна|подтверждаю|оформляйте|нет|не|отмена|отменить|da|ja|yes|ok|okay|gut|passt|einverstanden|nein|no|cancel|abbrechen)$/i;
const isAmbiguousShort = AMBIGUOUS_SHORT.test(confirmProbe.replace(/[\s.!?,…]+$/g, '').toLowerCase());
let langSource = 'detect';
if (isShortUtterance && isAmbiguousShort && fresh && prev.lang) { lang = prev.lang; langSource = 'ctx'; }

// Наследуем товар только когда его нет в текущей реплике И видно, что это продолжение:
// либо клиент уточнил цвет/вариант, либо фраза явно ссылается на предыдущее.
if (!product && fresh && (slots.color || slots.variant || FOLLOWUP.test(sourceText) || productIsGeneric || isConfirm || colloquialVariant)) {
  product = prev.product;
  inherited = true;
  queryNorm = `${prev.product}: ${queryNorm}`;
  // Замок из промпта, применённый кодом: если товар известен, это не оффтоп.
  if (intent === 'none') { intent = 'stock'; conf = 'mid'; }
}

// Фикс 18.08 (прогон 1853 — главный обрыв сделки): «Оформите мне белый чайник на
// 1,7 литра» — классификатор по своему промпту относит ЛЮБОЕ «оформление заказа» к FAQ,
// и клиент вместо товара получал справку «как оформить заказ» — сделка рвалась на самом
// важном шаге. ORDER_CONFIRM выше обходит faq-гвард ТОЛЬКО внутри окна awaitingConfirm,
// а здесь окна не было: предыдущая реплика вернула ambiguous, кнопка не выставлялась.
// Правило: глагол намерения купить + КОНКРЕТНЫЙ товар (названный или унаследованный)
// = склад, а не справочник. Дальше 10b сам решит, однозначен товар или нужно уточнение.
// Гварды уже внутри orderIntentConfirm: «Как оформить заказ?» содержит «?» → остаётся faq.
// Жалобу не перехватываем: «хочу оформить возврат» должно идти в эскалацию, а не в каталог.
if (product && orderIntentConfirm && intent !== 'complaint') {
  intent = 'stock';
  if (conf === 'low') conf = 'mid';
}

// «Да» подтверждает ЗАКАЗ, только если предыдущая реплика ассистента предлагала ОДНОЗНАЧНЫЙ
// товар (флаг awaitingConfirm — нода 10b). Без привязки к этому флагу любое голое «да» в
// разговоре ложно читалось бы как согласие купить. Запрос Dennis 14.08: подтверждение должно
// завершать сделку (эскалация оператору в ноде 13), а не повторно уходить в поиск по складу.
const orderConfirmed = !!(prev && prev.awaitingConfirm && (isConfirm || orderIntentConfirm));
// Детали товара для уведомления оператору (запрос Dennis 14.08, прогон 1071:
// в тексте эскалации был только транскрипт «Да.», оператор не знал, что заказано).
// Берём из prev ДО сброса флага — они туда положились в тот же момент, что и awaitingConfirm (нода 10b).
let confirmedOrder = null;
if (orderConfirmed) {
  confirmedOrder = {
    name: prev.confirmName || prev.product || '',
    color: prev.confirmColor || '',
    price: prev.confirmPrice != null ? prev.confirmPrice : null
  };
  try { store.dialogCtx[chatId].awaitingConfirm = false; } catch (e) {}
}

// E10 (кнопка подтверждения заказа, решение Dennis): отказ на предложение оформить заказ должен
// закрывать окно ожидания так же, как и подтверждение, но без оффтоп-отказа и без эскалации.
// Гейт тот же prev.awaitingConfirm — вне этого окна «нет» работает как раньше (не decline).
const DECLINE_CONFIRM = /^(нет|не надо|не нужно|спасибо,? нет|nein|no)(?![а-яёіїєa-z])/i;
// Confirm-этап переиспользует кнопку мастера «Otmenitь zakaz» (решение Dennis) — отдельный алиас, т.к. «отменить» не проходит через lookahead выше (буква после корня «отмен»).
const CANCEL_CONFIRM = /^(отмена|отменить|cancel|abbrechen)/i;
const declineOrder = !orderConfirmed && !!(prev && prev.awaitingConfirm) && !hasQuestionMark && (DECLINE_CONFIRM.test(confirmProbe) || CANCEL_CONFIRM.test(confirmProbe));
if (declineOrder) {
  try { store.dialogCtx[chatId].awaitingConfirm = false; } catch (e) {}
}

// Накапливаем НЕ ТОЛЬКО товар, но и уточнения (цвет, объём).
// Повод (прогоны 1024→1025→1023): клиент сказал «белый на 1,7 литра», на следующей
// реплике унаследовался только товар — и ассистент снова предлагал все 5 вариантов
// и снова спрашивал «какой именно?». Разговор шёл по кругу, клиент не мог купить.
// Классификатор иногда подмешивает цвет/объём из ИСТОРИИ диалога в свежий, более широкий
// вопрос, где клиент их не называл. Повод (прогон 1050): «Сколько у вас чайников?» —
// без единого слова о цвете — вернулось slots.color: "белый", slots.variant: "1,7 литра"
// из предыдущей реплики — ответ сузился до одного варианта вместо всех пяти (и «самый
// дешёвый?» в 1052 ответил ценой не того чайника). Доверяем только тому, что реально
// произнесено в ЭТОЙ реплике: цвет и цифры объёма должны буквально встречаться в sourceText.
const textLower = sourceText.toLowerCase();
// ё/е схлопываем: классификатор возвращает «черный», клиент говорит «чёрный» (прогон 1852) —
// без нормализации анти-галлюцинационный гвард ниже гасил законный цвет.
const deyo = (s) => String(s == null ? '' : s).toLowerCase().replace(/ё/g, 'е');
const textNorm = deyo(sourceText);
let curColor = String(slots.color || '').trim();
// МУЛЬТИТОВАР (18.08, прогоны 1851/1852): на «белый и ещё один чёрный» классификатор отдаёт
// slots.color одной строкой «белый, чёрный». Дословно такая строка в тексте не встречается —
// гвард гасил цвет ЦЕЛИКОМ, 10b не мог сузить, ambiguous держался вечно, awaitingConfirm не
// выставлялся, кнопка заказа не появлялась. Клиент три реплики подряд слышал «какой именно?»
// и не мог купить. Корзину не строим (см. роадмап): берём ПЕРВЫЙ названный товар, остальные
// отдаём в extra_colors — нода 10b честно скажет, что их оформим следующим заказом.
let extraColors = [];
if (curColor && /[,;]|\bи\b|\bта\b|\bund\b|\band\b/i.test(curColor)) {
  const parts = curColor.split(/\s*(?:[,;]|\bи\b|\bта\b|\bund\b|\band\b)\s*/i).map(s => s.trim()).filter(Boolean);
  const present = parts.filter(p => textNorm.includes(deyo(p)));
  if (present.length) { curColor = present[0]; extraColors = present.slice(1); }
}
if (curColor && !textNorm.includes(deyo(curColor))) curColor = '';
let curVariant = String(slots.variant || '').trim();
if (curVariant) {
  const vDigits = (curVariant.match(/\d/g) || []).join('');
  if (vDigits && !textLower.replace(/[.,]/g, '').includes(vDigits)) curVariant = '';
}
// Фикс 15/16.08 (прогоны 1442): классификатор кладёт словесный синоним («компактный») в slots.variant НЕ пустым — старая проверка «!curVariant» никогда не срабатывала, а 10b фильтрует только по цифрам — словесный вариант без цифр ей бесполезен, даже если классификатор его вернул. Приоритет: colloquialVariant, если в curVariant нет своих цифр.
if (colloquialVariant && !/\d/.test(curVariant)) curVariant = colloquialVariant;
let color = curColor;
let variant = curVariant;

// Явное повторение ШИРОКОГО вопроса о том же товаре («Сколько у вас чайников?»
// после того как уже сузили до одного варианта) — сигнал сбросить сужение, а не сохранить его.
// Решение оркестратора 14.08 (по прогонам 1050/1052): узкий цвет/объём, молча переживший
// в новом широком вопросе, давал неверный ответ («самый дешёвый» считался от одного
// варианта вместо пяти). Признаки сброса: товар назван СЕЙЧАС явно (не унаследован),
// в реплике нет цвета/объёма, и вопрос широкий. Эллиптические уточнения типа «а чёрный
// есть?» товар не называют — под сброс не попадают, наследуют как раньше.
const productNamedNow = !!String(slots.product || '').trim() && !productIsGeneric;
const BROAD = /сколько|какие|вариант|есть ли|скільки|які|wie viele|welche/i;
const isResetQuestion = productNamedNow && !curColor && !curVariant && BROAD.test(sourceText);

// Уточнения переносим только пока речь об ОДНОМ и том же товаре:
// сменил товар — старый цвет и объём больше не значат ничего.
const sameProduct = fresh && product && String(prev.product || '') === product;
if (sameProduct && !isResetQuestion) {
  if (!color) color = String(prev.color || '');
  if (!variant) variant = String(prev.variant || '');
}

if (product) store.dialogCtx[chatId] = { product, color, variant, lang: lang || (prev && prev.lang) || '', ts: Date.now() };

return [{ json: {
  intent,
  confidence: conf,
  query_norm: queryNorm,
  slots: Object.assign({}, slots,
    product ? { product } : {},
    color ? { color } : {},
    variant ? { variant } : {}),
  source_text: sourceText,
  lang,
  lang_source: langSource,
  fallback,
  ctx_inherited: inherited,
  ctx_slots: { product, color, variant },
  extra_colors: extraColors,
  orderConfirmed,
  confirmedOrder,
  declineOrder
}, pairedItem: { item: 0 } }];

// Ветка «Склад»: сопоставление запроса с каталогом, агрегация, echo-back (план §5.4).

// --- что искал клиент
let product = '', color = '', variant = '', sourceText = '', chatId = 'unknown', extraColors = [];
try {
  const n = $('8. Нормализация intent + keyword-fallback').first().json;
  product = String((n.slots && n.slots.product) || '');
  color = String((n.slots && n.slots.color) || '');
  variant = String((n.slots && n.slots.variant) || '');
  sourceText = String(n.source_text || '');
  extraColors = Array.isArray(n.extra_colors) ? n.extra_colors : [];
  if (!product) product = String(n.query_norm || '');
} catch (e) {}
if (!product) product = sourceText;
try { chatId = String($('1. Telegram Trigger (voice)').first().json.message.chat.id || 'unknown'); } catch (e) {}

// Флаг «сделка на пороге закрытия» (запрос Dennis 14.08): по умолчанию снят на КАЖДОЙ реплике —
// выставляется в true ниже только для однозначно найденного товара. Нода 8 на следующей
// реплике читает его, чтобы отличить «да» = подтверждение заказа от «да» просто в разговоре.
try {
  const s0 = $getWorkflowStaticData('global');
  s0.dialogCtx = s0.dialogCtx || {};
  if (s0.dialogCtx[chatId]) s0.dialogCtx[chatId].awaitingConfirm = false;
} catch (e) {}

const items = $input.all().map(i => i.json);

// Сбой самого источника — это НЕ «товара нет». Говорим честно (R6).
if (items.length && items[0] && items[0].error !== undefined) {
  return [{ json: { branch: 'stock', found: false, source_error: true, source_text: sourceText,
    answer_facts: 'Сейчас не получается открыть каталог остатков — техническая неполадка на нашей стороне. Повторите вопрос немного позже.' }, pairedItem: { item: 0 } }];
}

const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/ё/g, 'е')
  .replace(/[^a-zа-я0-9 ]+/gi, ' ').replace(/\s+/g, ' ').trim();

const STOP = ['сколько','осталось','есть','вас','наличии','наличие','склад','складе',
              'штук','мне','нужен','нужна','какие','какой','это','пожалуйста','подскажите',
              // Предлоги (18.08.2026): без них мягкий матчинг на «подарок ДЛЯ мамы»
              // предлагал «Фильтр ДЛЯ чайника» — совпадение по предлогу, а не по смыслу.
              'для','или','под','над','при','про'];

// Составные слова: «электрочайник» → «электро» + «чайник»
const expand = (w) => {
  for (const p of ['электро', 'мини', 'микро', 'авто']) {
    if (w.startsWith(p) && w.length > p.length + 3) return [p, w.slice(p.length)];
  }
  return [w];
};

// Грубый стемминг: первые 6 символов — снимает разницу падежей (лампы/лампа),
// но не схлопывает разные слова с общим коротким началом. Было 4 символа: «компьютер» и
// «компактный» совпадали по «комп», и клиенту вместо честного «нет в наличии»
// ответили остатком чайника (прогон 956).
// Материал/цвет — разговорная форма прилагательного не совпадает по стему с названием в каталоге
// (15.08.2026, разбор прогона 1408): «стеклянный» режется до «стекля», а в каталоге «стекло» —
// совпадение по префиксу ломается на declension. Подменяем на канон ДО стемминга.
const MATERIAL_SYNONYMS = [
  { re: /^стеклянн/, canon: 'стекло' },
  { re: /^прозрачн/, canon: 'стекло' },
];
// Фикс 15/16.08 (прогон 1441): классификатор кладёт материал («стеклянный») в slots.variant, НЕ в slots.product —
// старый цикл по product его никогда не видел (живой прогон отдал все 5 вариантов вместо одного). Сканируем оба поля.
const stems = [];
for (const w of norm(product + ' ' + variant).split(' ')) {
  if (!w || w.length < 3 || STOP.includes(w)) continue;
  let ww = w;
  for (const syn of MATERIAL_SYNONYMS) if (syn.re.test(w)) { ww = syn.canon; break; }
  for (const part of expand(ww)) if (part.length >= 4) stems.push(part.slice(0, 6));
}

// Строки каталога без служебной «Итого» и без пустых артикулов.
// Последняя строка листа содержит итог 524 шт — в сумму она попасть не должна (AE-11).
const rows = items.filter(r => String(r['Артикул'] || '').trim() && norm(r['Наименование товара']) !== 'итого');

const qty = (r) => Number(String(r['Остаток (шт)'] != null ? r['Остаток (шт)'] : 0).replace(',', '.')) || 0;
const priceOf = (r) => Number(String(r['Цена (EUR)'] != null ? r['Цена (EUR)'] : 0).replace(',', '.')) || 0;
const nameOf = (r) => String(r['Наименование товара'] || '');

// Совпадение считается только по НАЧАЛУ слова, а не по подстроке где попало внутри.
// Повод (прогон 947): запрос «столовая ложка» давал основу «стол», а она находилась
// внутри слова «наСТОЛьная» — и клиенту выдавались остатки ламп как остатки ложек.
// Самый опасный вид ошибки: не отказ и не сбой, а уверенный ответ с чужими числами.
// Взвешенный матчинг: совпадение с ПЕРВЫМ словом названия весит 2, с остальными
// словами названия и категорией — 1. Иначе «Фильтр для чайника» и «Чайник электрический»
// получали одинаковый score по стему «чайник» (стем матчит начало слова «чайника») —
// клиенту озвучивали фильтры как чайники (прогоны 1029/1031: «113 чайников» вместо 53).
// Товар (первое слово = сам продукт) теперь всегда перевешивает аксессуар,
// а запрос «фильтр» по-прежнему находит фильтр — его первое слово и есть «фильтр».
let best = [], bestScore = 0;
for (const r of rows) {
  const nameWords = norm(r['Наименование товара']).split(' ').filter(Boolean);
  const restWords = nameWords.slice(1).concat(norm(r['Категория']).split(' ').filter(Boolean));
  const firstWord = nameWords[0] || '';
  let score = 0;
  for (const s of stems) {
    if (firstWord.startsWith(s)) score += 2;
    else if (restWords.some(w => w.startsWith(s))) score += 1;
  }
  if (score > bestScore) { bestScore = score; best = [r]; }
  else if (score === bestScore && score > 0) best.push(r);
}

if (!best.length) {
  // КАТЕГОРИЙНЫЙ ЗАПРОС (18.08.2026, находка Dennis на живом тесте): клиент спрашивает
  // не про товар, а про КАТЕГОРИЮ или повод: «какие есть кухонные товары», «товары для сада»,
  // «подарок для мамы». Стемминг по префиксу такое не ловит из-за склонения («кухни» ≠ «Кухня»,
  // «кухонные» ≠ «Кухня») — и клиент получал глухое «не найдено», хотя в категории «Кухня»
  // лежат 12 позиций, включая чайники. Синонимы проверены симуляцией на реальных категориях БД (9/9).
  const catText = norm(product + ' ' + sourceText);
  const CATEGORY_SYNONYMS = [
    { re: /кух|готов|посуд|чаепит/, cat: 'кухня' },
    { re: /дом|уют|интерьер|спальн|плед/, cat: 'дом' },
    { re: /канцеляр|офис|школ|учеб|записк/, cat: 'канцелярия' },
    { re: /свет|освещ|светильник|лампоч/, cat: 'освещение' },
    { re: /спорт|отдых|туризм|поход|пикник/, cat: 'спорт и отдых' },
  ];
  const allCats = Array.from(new Set(rows.map(r => String(r['Категория'] || '').trim()).filter(Boolean)));
  const catHit = CATEGORY_SYNONYMS.find(c => c.re.test(catText));
  if (catHit) {
    const inCat = rows.filter(r => norm(r['Категория']) === catHit.cat && qty(r) > 0);
    if (inCat.length) {
      const uniq = [];
      for (const r of inCat) {
        const nm = nameOf(r);
        if (!uniq.some(u => u.n === nm)) uniq.push({ n: nm, p: priceOf(r) });
      }
      const catName = String(inCat[0]['Категория'] || catHit.cat);
      return [{ json: { branch: 'stock', found: true, ambiguous: true, category: catName,
        total: inCat.reduce((s, r) => s + qty(r), 0),
        variants: uniq.map(u => u.n), accessory: null, source_text: sourceText,
        answer_facts: `Клиент спросил про КАТЕГОРИЮ, а не про конкретный товар. В категории «${catName}» есть в наличии: ${uniq.map(u => u.n + ' — ' + u.p + ' евро').join('; ')}. Назови эти позиции коротко и живо, без количеств и артикулов, затем спроси, что из этого интересует.` }, pairedItem: { item: 0 } }];
    }
  }
  // Точного совпадения нет — ищем ближайшую замену в наличии по частичному описанию
  // (запрос Dennis 14.08: не бросать клиента на голом «не найдено», а предложить то, что реально
  // есть на складе, если оно хоть отдалённо похоже на запрос; прогоны 1057/1058:
  // «беспроводные наушники»/«маркеры» — плоский отказ без альтернативы.
  // Матчинг ЗАМЕТНО мягче основного (A1): подстрока в любом месте, стем от 3 символов,
  // без обрезки до 6 — иначе «маркер» и «наушники», у которых в каталоге вообще нет
  // пересечения по словам, получили бы случайную «похожую» подсказку. Предлагаем
  // ТОЛЬКО когда есть реальное текстовое пересечение — выдумывать связи запрещено.
  const looseStems = [];
  for (const w of norm(product).split(' ')) {
    if (!w || w.length < 3 || STOP.includes(w)) continue;
    for (const part of expand(w)) if (part.length >= 3) looseStems.push(part);
  }
  let altBest = [], altScore = 0;
  for (const r of rows) {
    const hay = norm(nameOf(r)) + ' ' + norm(r['Категория']);
    const score = looseStems.filter(s => hay.includes(s)).length;
    if (score > altScore) { altScore = score; altBest = [r]; }
    else if (score === altScore && score > 0) altBest.push(r);
  }
  if (altBest.length) {
    const alt = altBest.filter(r => qty(r) > 0).sort((a, b) => qty(b) - qty(a))[0] || altBest[0];
    return [{ json: { branch: 'stock', found: false, suggested: true, source_text: sourceText,
      answer_facts: `Товар «${product}» в каталоге Nordwaren не найден. Точных данных об остатке нет. БЛИЖАЙШАЯ ЗАМЕНА ИЗ НАЛИЧИЯ (предложить честно как альтернативу, не как то, что клиент просил): ${nameOf(alt)}${alt['Цвет'] ? ', ' + alt['Цвет'] : ''}, ${priceOf(alt)} евро, в наличии ${qty(alt)} шт.` }, pairedItem: { item: 0 } }];
  }
  // Честное «нет» + ориентиры: клиент не должен угадывать, чем торгует магазин (18.08.2026):
  // на «товары для сада» / «подарок для мамы» говорим «нет» и сразу называем направления каталога.
  return [{ json: { branch: 'stock', found: false, source_text: sourceText,
    answer_facts: `Товар «${product}» в каталоге Nordwaren не найден. Точных данных об остатке нет. ЧТО ЕСТЬ В КАТАЛОГЕ (назови эти направления одной фразой, чтобы клиент сориентировался): ${allCats.join(', ')}.` }, pairedItem: { item: 0 } }];
}

// Сужаем выбор по тому, что клиент уже назвал.
// Сначала цвет, потом ОБЪЁМ — раньше объём не читался вообще, и на «белый на 1,7 литра»
// ассистент всả равно переспрашивал «какой именно?» (прогон 1024) — разговор шёл по кругу.
const byColor = color ? best.filter(r => norm(r['Цвет']).includes(norm(color))) : [];
let picked = byColor.length ? byColor : best;

// Объём сравниваем числом: клиент говорит «1,7 литра», в каталоге «1.7л» —
// разные записи одного и того же.
const vNum = (String(variant).match(/\d+[.,]?\d*/) || [''])[0].replace(',', '.');
if (vNum) {
  const byVariant = picked.filter(r => String(r['Наименование товара'] || '').replace(',', '.').includes(vNum));
  if (byVariant.length) picked = byVariant;
}

const total = picked.reduce((s, r) => s + qty(r), 0);
// Цена в разбивке — опора для «самый дешёвый» / «до N евро» (прогоны 1034/1035);
// в речь по умолчанию модель её не тянет (см. промпт ноды 14), только когда клиент спросит.
const variants = picked.map(r => `${r['Наименование товара']}${r['Цвет'] ? ', ' + r['Цвет'] : ''} — ${qty(r)} шт, ${priceOf(r)} евро`);
const ambiguous = picked.length > 1;
// Запрос Dennis 14.08: уведомление оператору при подтвержденном заказе не содержало товар
// (прогон 1071: только chat_id/имя/тип/транскрипт «Да.»). Сохраняем товар/цвет/цену
// в тот же момент, когда выставляем awaitingConfirm — нода 8 прочтёт на следующей реплике.
try {
  const s1 = $getWorkflowStaticData('global');
  if (s1.dialogCtx[chatId]) {
    s1.dialogCtx[chatId].awaitingConfirm = !ambiguous;
    if (!ambiguous) {
      const r0 = picked[0];
      const newName = r0['Наименование товара'] || '';
      s1.dialogCtx[chatId].confirmName = newName;
      s1.dialogCtx[chatId].confirmColor = r0['Цвет'] || '';
      s1.dialogCtx[chatId].confirmPrice = priceOf(r0);

      // Найдено 15.08 (разбор прогонов 1370–1391, жалоба Dennis «неверная цена в заказе»):
      // если клиент раньше голосом/кнопкой подтвердил ДРУГОЙ товар и мастер ещё стоит на
      // шаге 1 (ничего не ответил, TTL 30 мин ещё не истёк) — а сейчас нашлись НОВОЕ однозначное
      // совпадение для ДРУГОГО товара — старый мастер уже неактуален и тихо ждёт ответа про чужой
      // товар. Без сброса следующий текст клиента тихо ушёл бы в СТАРЫЙ мастер (прогоны
      // 1375→1391: клиент обсуждал белый чайник, а в сводке вылез забытый прозрачный за 34.9€).
      // Сбрасываем ТОЛЬКО нетронутый (step===1) мастер — если клиент уже начал вводить имя/
      // адрес для прежнего заказа — не трогаем (могут быть легитимные уточнения).
      try {
        const wf = s1.orderForm && s1.orderForm[chatId];
        if (wf && wf.step === 1 && wf.product && wf.product.name && wf.product.name !== newName) {
          delete s1.orderForm[chatId];
        }
      } catch (e) {}
    }
  }
} catch (e) {}

// --- Сопутствующий товар (кросс-сейл, 14.08.2026) ------------------------------
// Кандидат берётся ТОЛЬКО из этого же каталога — модели запрещено выдумывать товары,
// а выдуманный «фильтр к чайнику» — это обещание того, чего нет на складе.
// ❗ Настоящих аксессуаров в каталоге нет (ни фильтров, ни чашек), поэтому логика такая:
//   1) осмысленная пара по сценарию использования (чайник ↔ термос — оба про горячие напитки);
//   2) иначе — сосед по категории, самый доступный по цене (не дороже основной покупки).
// 14.08.2026 в каталог добавлены НАСТОЯЩИЕ аксессуары (ACC-6001–6007) — по одному
// на каждую категорию, чтобы у любого товара было осмысленное дополнение.
// До этого аксессуаров не было вообще, и кросс-сейл приходилось строить на соседях
// по категории («к чайнику тостер») — честно, но слабо как продажа.
const AFFINITY = {
  'чайник': ['фильтр', 'накип', 'чашек'],
  'термос': ['чехол'],
  'лампа': ['лампочк'],
  'плед': ['подушк'],
  'блокнот': ['стикер', 'ручек'],
  'ручек': ['блокнот', 'стикер'],
  'тостер': ['чашек'],
  'блендер': ['чашек'],
  'мультиварк': ['чашек'],
};

const pickCross = (base) => {
  const baseName = norm(nameOf(base));
  const baseCat = norm(base['Категория']);
  // Предлагаем только то, что реально есть на складе, и не тот же самый товар
  const stock = rows.filter(r => qty(r) > 0 && norm(nameOf(r)) !== baseName);

  for (const key of Object.keys(AFFINITY)) {
    if (!baseName.includes(key)) continue;
    for (const partner of AFFINITY[key]) {
      const hit = stock.filter(r => norm(nameOf(r)).includes(partner))
                       .sort((a, b) => qty(b) - qty(a))[0];
      if (hit) return hit;
    }
  }

  const sameCat = stock.filter(r => norm(r['Категория']) === baseCat && priceOf(r) <= priceOf(base));
  if (!sameCat.length) return null;
  return sameCat.sort((a, b) => priceOf(a) - priceOf(b))[0];
};

const crossText = (c) => c
  ? ` СОПУТСТВУЮЩЕЕ (предложить ОДНОЙ короткой фразой и только если уместно; не навязывать, при отказе не повторять): ${nameOf(c)}${c['Цвет'] ? ', ' + String(c['Цвет']).toLowerCase() : ''}, ${priceOf(c)} евро, в наличии ${qty(c)} шт.`
  : '';

let facts;
let crossAccessory = null;
if (!ambiguous) {
  const r = picked[0];
  const cross = pickCross(r);
  crossAccessory = cross ? { name: nameOf(cross), price: priceOf(cross) } : null;
  // E11 (сопутствующий товар в заказе): кладём его СТРУКТУРНО (не только текстом в answer_facts для
  // голоса) — и в dialogCtx для кнопки подтверждения, и в ответ, чтобы его можно было
  // добавить в заказ одним нажатием кнопки, а не только услышать о нём.
  try {
    const s3 = $getWorkflowStaticData('global');
    if (s3.dialogCtx[chatId]) {
      s3.dialogCtx[chatId].confirmAccessoryName = crossAccessory ? crossAccessory.name : '';
      s3.dialogCtx[chatId].confirmAccessoryPrice = crossAccessory ? crossAccessory.price : null;
    }
  } catch (e) {}
  // МУЛЬТИТОВАР (18.08, прогоны 1851/1852): клиент назвал несколько товаров сразу.
  // Мастер заказа рассчитан на ОДНУ позицию + аксессуар (orderForm.product — один объект),
  // мультипозиционная корзина — отдельная фича в роадмапе. Здесь честно оформляем первый
  // товар и вслух говорим про остальные — вместо того чтобы молча их потерять.
  const multiNote = extraColors.length
    ? ` ВАЖНО: клиент назвал ещё ${extraColors.length === 1 ? 'один вариант' : 'несколько вариантов'} (${extraColors.join(', ')}). В одном заказе оформляется только одна позиция — скажи об этом честно и коротко: сейчас оформляем этот товар, остальное добавим следующим заказом.`
    : '';
  facts = `Товар: ${r['Наименование товара']}${r['Цвет'] ? ', цвет ' + r['Цвет'] : ''}. В наличии ${qty(r)} шт. Цена ${r['Цена (EUR)']} евро.` + multiNote + crossText(cross);
} else {
  // Требование Dennis (14.08): перечислять ВСЕ варианты, не выбирать за клиента различие.
  // Раньше инструкция «озвучивать все варианты» была только в промпте ноды 14 и терялась
  // при откате правок через UI (v29, 09:04:58) — теперь она закреплена и здесь, в фактах.
  const clarify = ' Перечисли клиенту ВСЕ варианты из разбивки (модель, цвет, объём — что есть в наличии) одной живой фразой, затем коротко спроси, какой подходит.';

  facts = `Запрос клиента: ${product}. Всего в наличии ${total} шт по ${picked.length} вариантам. Разбивка: ${variants.join('; ')}.` + clarify;
}

return [{ json: { branch: 'stock', found: true, ambiguous, total, variants, accessory: crossAccessory, source_text: sourceText, answer_facts: facts }, pairedItem: { item: 0 } }];

// Score-gate: отбрасываем нерелевантное, пустой контекст = честный отказ (план §5.5).
//
// ПЕРЕКАЛИБРОВАНО 14.08.2026 под эмбеддер bge-m3 (было 0.45 под OpenAI).
// Старый порог переносить было нельзя: у разных эмбеддеров разная шкала близости.
// Замер на живой коллекции nordwaren_faq_local (8 вопросов, ru/de/uk):
//   ответ В СПРАВОЧНИКЕ ЕСТЬ   → 0.636 … 0.836
//   ответа НЕТ (погода, футбол) → 0.280 … 0.507
// Разрыв чистый, порог ставим посередине. Относительный отбор сохранён:
// он спасает, когда два фрагмента идут вплотную и нужный — второй.
const TH = 0.55;      // абсолютный минимум: ниже — «вообще не про то»
const GAP = 0.05;     // допустимое отставание от лучшего фрагмента

let sourceText = '';
try {
  sourceText = String($('8. Нормализация intent + keyword-fallback').first().json.source_text || '');
} catch (e) { sourceText = ''; }

const items = $input.all().map(i => i.json).filter(Boolean);

// 1) Явный сбой источника — это НЕ «нет основания».
// Ловим ДВА вида сбоя:
//   а) элемент с полем error;
//   б) МОЛЧАЛИВЫЙ — при onError=continueErrorOutput нода Qdrant отдаёт на error-выход
//      ИСХОДНЫЙ элемент БЕЗ поля error. Прогон 982 (14.08.2026): сервер Qdrant лежал,
//      нода упала с «fetch failed», а клиент услышал «такой информации нет» — то есть враньё
//      вместо честного признания сбоя, причём про доставку, которая в справочнике ЕСТЬ.
//      Такой элемент узнаётся по полям классификатора: у фрагмента справочника их нет.
const srcFailed = items.length && items[0] && (
  items[0].error !== undefined ||
  (items[0].query_norm !== undefined && items[0].intent !== undefined)
);
if (srcFailed) {
  return [{ json: { branch: 'faq', grounded: false, source_error: true, source_text: sourceText,
    answer_facts: 'Сейчас не получается свериться со справочником — техническая неполадка на нашей стороне. Пожалуйста, повторите вопрос позже или напишите в поддержку.' }, pairedItem: { item: 0 } }];
}

// Текст фрагмента может лежать на верхнем уровне или внутри document — берём оба случая
const textOf = (d) => String(
  (d && d.pageContent) ||
  (d && d.document && d.document.pageContent) ||
  (d && d.text) || ''
).trim();

const scoreOf = (d) => {
  if (d && typeof d.score === 'number') return d.score;
  if (d && d.metadata && typeof d.metadata.score === 'number') return d.metadata.score;
  return 1; // скора нет — не отбрасываем фрагмент молча
};

const withText = items.filter(d => textOf(d));

// 2) Ничего не нашлось / нода вернула пустоту — всё равно отвечаем голосом (R6)
if (!withText.length) {
  return [{ json: { branch: 'faq', grounded: false, source_text: sourceText,
    answer_facts: `Вопрос клиента: ${sourceText}\n\nВ справочнике Nordwaren нет фрагмента, отвечающего на этот вопрос. Надо вежливо сказать, что такой информации нет, и предложить обратиться в поддержку. Отвечать из общих знаний нельзя.` }, pairedItem: { item: 0 } }];
}

// 3) Отсекаем нерелевантное по score
const maxScore = Math.max(...withText.map(scoreOf));
const docs = withText.filter(d => scoreOf(d) >= TH && scoreOf(d) >= maxScore - GAP);

if (!docs.length) {
  return [{ json: { branch: 'faq', grounded: false, source_text: sourceText,
    scores: withText.map(scoreOf),
    answer_facts: `Вопрос клиента: ${sourceText}\n\nНайденные фрагменты справочника недостаточно близки к вопросу. Надо вежливо сказать, что такой информации нет. Отвечать из общих знаний нельзя.` }, pairedItem: { item: 0 } }];
}

const context = docs.map(textOf).join('\n---\n');

return [{ json: {
  branch: 'faq',
  grounded: true,
  chunks: docs.length,
  scores: docs.map(scoreOf),
  source_text: sourceText,
  context,
  answer_facts: `Вопрос клиента: ${sourceText}\n\nФрагменты справочника Nordwaren — единственный допустимый источник ответа:\n${context}`
}, pairedItem: { item: 0 } }];

// Вежливый голосовой отказ: оффтоп (intent=none, R8a) или сработавшие гуардрейлы.
// Клиент не должен слышать разницы, но в журнале она должна оставаться.
const j = $input.first().json;

// У гуардрейл-ноды текст лежит в guardrailsInput, у ветки оффтопа — в source_text
let sourceText = String(j.source_text || j.guardrailsInput || j.text || '');
if (!sourceText) {
  try { sourceText = String($('8. Нормализация intent + keyword-fallback').first().json.source_text || ''); } catch (e) {}
}
if (!sourceText) {
  for (const n of ['5c. STT — whisper.cpp (локально, Tailscale)', '5. STT — Whisper (auto)  [SWAP→LOCAL]']) {
    try {
      const t = String($(n).first().json.text || '');
      if (t) { sourceText = t; break; }
    } catch (e) {}
  }
}

// Какой контроль сработал и с какой уверенностью — нужно для разбора инцидентов
let guardrail = '';
try {
  const fired = (j.checks || []).filter(c => c && c.triggered);
  guardrail = fired.map(c => `${c.name} (${c.confidenceScore})`).join(', ');
} catch (e) { guardrail = ''; }

return [{
  json: {
    branch: 'none',
    guardrail,
    source_text: sourceText,
    answer_facts: 'Это вне моей компетенции. Я помогаю с наличием товаров и вопросами по заказу, оплате и доставке.'
  },
  pairedItem: { item: 0 }
}];

// Пустое/нераспознанное аудио (R8b) + circuit breaker (план §5.6, урок 274).
const N = 2; // после скольких неудач подряд зовём человека

let clientText = '', chatId = 'unknown';
try {
  const msg = $('1. Telegram Trigger (voice)').first().json.message || {};
  clientText = String(msg.text || msg.caption || '');
  chatId = String((msg.chat && msg.chat.id) || 'unknown');
} catch (e) {}

// Счётчик неудач по каждому чату. staticData переживает выполнения активного воркфлоу.
// ❗ В ручных запусках (Execute workflow) staticData НЕ сохраняется — проверять только живыми сообщениями боту.
let attempts = 1;
try {
  const store = $getWorkflowStaticData('global');
  store.failedAttempts = store.failedAttempts || {};
  attempts = (store.failedAttempts[chatId] || 0) + 1;
  store.failedAttempts[chatId] = attempts;

  if (attempts >= N) store.failedAttempts[chatId] = 0; // после эскалации счёт начинается заново
} catch (e) {}

if (attempts >= N) {
  return [{ json: {
    branch: 'escalate',
    escalate: true,
    attempts,
    source_text: clientText,
    answer_facts: 'Распознать обращение не удалось уже второй раз подряд. Нужно спокойно сказать, что обращение передаём живому оператору и специалист свяжется с клиентом.'
  }, pairedItem: { item: 0 } }];
}

return [{ json: {
  branch: 'repeat',
  escalate: false,
  attempts,
  source_text: clientText,
  answer_facts: 'Не расслышал сообщение. Повторите, пожалуйста, запрос.'
}, pairedItem: { item: 0 } }];

