parameters.jsCode:
// Audit log с redaction [PII] (урок 274 + TOMs). Храним транскрипт, не сырое аудио.
// Вход — прямо из единой точки ответа, параллельно озвучке.
const j = $json;
const t = String(j.source_text || '');

// Телефоны в транскрипте маскируем до записи в журнал
const redact = t.replace(/\+?\d[\d\s\-()]{6,}\d/g, '[PHONE]');

return [{ json: {
  ts: new Date().toISOString(),
  branch: j.branch || 'unknown',
  lang: j.lang || '',
  escalated: j.escalate === true,
  attempts: j.attempts || 0,
  guardrail: j.guardrail || '',
  transcript_redacted: redact,
  answer_facts: j.answer_facts || ''
}, pairedItem: { item: 0 } }];

// Единственная точка сборки ответа: Склад / FAQ / оффтоп / повторить / эскалация.
const src = $input.first().json;

// Что сказал или написал клиент. Главный источник — собственный вход:
// каждая ветка несёт source_text с собой, так как сквозные ссылки после развилки ненадёжны.
let clientText = String(src.source_text || '');

if (!clientText) {
  try { clientText = String($('8. Нормализация intent + keyword-fallback').first().json.source_text || ''); } catch (e) {}
}
if (!clientText) {
  for (const n of ['5c. STT — whisper.cpp (локально, Tailscale)', '5. STT — Whisper (auto)  [SWAP→LOCAL]']) {
    try {
      const t = String($(n).first().json.text || '');
      if (t) { clientText = t; break; }
    } catch (e) {}
  }
}

let uiLang = '', chatId = 'unknown', clientName = '', clientUsername = '';
try {
  const msg = $('1. Telegram Trigger (voice)').first().json.message || {};
  if (!clientText) clientText = String(msg.text || msg.caption || '');
  uiLang = String((msg.from && msg.from.language_code) || '');
  chatId = String((msg.chat && msg.chat.id) || 'unknown');
  clientName = String((msg.from && msg.from.first_name) || '');
  clientUsername = String((msg.from && msg.from.username) || '');
} catch (e) {}

// Язык ответа = язык обращения. Порядок источников, от надёжного к запасному:
// 1) код ISO от классификатора (только он различает ru и uk — алфавит не различает);
// 2) он же из ноды 8; 3) алфавит самого обращения; 4) язык интерфейса Telegram; 5) немецкий.
// Интерфейс Telegram стоит НИЖЕ алфавита осознанно: это настройка телефона сотрудника,
// а не язык клиента — на прогоне 883 немецкий вопрос из-за него получил русский ответ.
let lang = String(src.lang || '').toLowerCase().trim().slice(0, 2);

if (!/^[a-z]{2}$/.test(lang)) {
  try { lang = String($('8. Нормализация intent + keyword-fallback').first().json.lang || '').toLowerCase().slice(0, 2); } catch (e) { lang = ''; }
}

// Язык, услышанный САМИМ распознаванием (сервис отдаёт поле lang с 14.08.2026,
// после перехода на двухпроходное распознавание).
// Стоит ВЫШЕ алфавита по двум причинам: алфавит не отличает русский от украинского
// и, главное, врёт целиком, если STT записал немецкую речь кириллицей (прогон 972).
if (!/^[a-z]{2}$/.test(lang)) {
  try {
    const l = String($('5c. STT — whisper.cpp (локально, Tailscale)').first().json.lang || '').toLowerCase().slice(0, 2);
    if (/^[a-z]{2}$/.test(l)) lang = l;
  } catch (e) {}
}

// Последний рубеж, когда кода не дали ни классификатор, ни распознавание:
// алфавит обращения, иначе язык интерфейса, иначе немецкий (язык компании).
if (!/^[a-z]{2}$/.test(lang)) {
  const ui = uiLang.toLowerCase().slice(0, 2);
  if (/[Ѐ-ӿ]/.test(clientText)) lang = 'ru';
  else if (/[a-zA-Z]/.test(clientText)) lang = 'de';
  else if (/^[a-z]{2}$/.test(ui)) lang = ui;
  else lang = 'de';
}

// «Да» после однозначного предложения товара (флаг из ноды 8, awaitingConfirm в ноде 10b) —
// подтверждение заказа. Раньше это тихо уходило назад в ветку «Склад», и нода 14 просто
// повторяла остаток/цену вместо того, чтобы завершить сделку (запрос Dennis 14.08).
// Передаём оператору через УЖЕ существующий канал эскалации (нода 20) — не дублируем механизм.
let orderConfirmed = false;
let declineOrder = false;
let orderSummary = '';
let confirmedOrderData = null;
try {
  const n8 = $('8. Нормализация intent + keyword-fallback').first().json;
  orderConfirmed = n8.orderConfirmed === true;
  declineOrder = n8.declineOrder === true;
  const co = n8.confirmedOrder;
  if (co) {
    confirmedOrderData = co;
    const parts = [co.name, co.color, (co.price != null ? co.price + ' евро' : '')].filter(Boolean);
    orderSummary = parts.join(', ');
  }
} catch (e) {}

let branch = src.branch || 'unknown';
let answerFactsOverride = null;
if (orderConfirmed) {
  branch = 'order_confirmed';
  answerFactsOverride = 'Клиент подтвердил намерение оформить заказ на ранее обсуждённый товар. Скажи коротко и по-деловому, что заявка передана оператору Nordwaren, который свяжется для оформления и оплаты — не называй остаток и цену повторно.';
  // Этап E: открываем окно ожидания текстовой формы (способ получения/адрес/email).
  // Данные товара берём из того же confirmedOrder, что и order_summary — не спрашиваем повторно.
  try {
    const storeE = $getWorkflowStaticData('global');
    storeE.orderForm = storeE.orderForm || {};
    // E8/Б3: повторный orderConfirmed при УЖЕ активном мастере не должен стирать его шаг/данные —
    // иначе ложное повторное «да» во время заполнения формы откатывает клиента на шаг 1.
    const existingWizard = storeE.orderForm[chatId];
    const wizardActive = !!(existingWizard && existingWizard.step && (Date.now() - (existingWizard.ts || 0)) < 30 * 60000);
    if (!wizardActive) {
      storeE.orderForm[chatId] = {
        step: 1,
        ts: Date.now(),
        product: {
          name: (confirmedOrderData && confirmedOrderData.name) || '',
          color: (confirmedOrderData && confirmedOrderData.color) || '',
          price: confirmedOrderData ? confirmedOrderData.price : null
        },
        data: {}
      };
    }
  } catch (e) {}
} else if (declineOrder || branch === 'decline') {
  // E10: отказ от предложения — закрываем окно спокойно, без оффтоп-отказа и без эскалации.
  // Гвард branch === 'decline' — для текстового/кнопочного пути (E10-фикс): E2a сама ставит
  // branch='decline', а нода 8 в этом прогоне вообще не выполнялась (текст, не голос), declineOrder
  // остался false из-за пойманного catch выше.
  branch = 'decline';
  answerFactsOverride = 'Клиент вежливо отказался от предложения оформить этот заказ. Скажи спокойно и коротко, например «хорошо, обращайтесь, если что-то понадобится» — НЕ предлагай тот же товар повторно.';
} else if (branch === 'confirm_expired') {
  // E10-фикс: окно подтверждения протухло (>30 мин) к моменту, когда клиент нажал кнопку/написал текстом —
  // честное «предложение устарело» вместо вводящего в заблуждение «не расслышал, повторите».
  answerFactsOverride = 'Клиент ответил на предложение оформить заказ, но окно ожидания уже закрылось (прошло больше 30 минут). Скажи вежливо, что предложение устарело, и предложи назвать товар заново, если он всё ещё нужен.';
}

// Удачный ответ сбрасывает счётчик circuit breaker — иначе клиента будет эскалировать вечно
if (branch !== 'repeat' && branch !== 'escalate') {
  try {
    const store = $getWorkflowStaticData('global');
    if (store.failedAttempts) store.failedAttempts[chatId] = 0;
  } catch (e) {}
}

// Приветствие + AI-дисклеймер (ст.50): здороваемся ОДИН раз на первом обращении клиента,
// дальше просто напоминаем о себе каждые 10 обращений без повторного «здравствуйте»
// (запрошено Dennis 13.08.2026 — то же правило заложено для будущего real-time звонка).
// Счётчик обращений — в staticData по chat_id, как и circuit breaker выше.
let disclaimerVariant = 'greeting';
try {
  const store = $getWorkflowStaticData('global');
  store.contactCount = store.contactCount || {};
  const count = (store.contactCount[chatId] || 0) + 1;
  store.contactCount[chatId] = count;
  disclaimerVariant = count === 1 ? 'greeting' : (count % 10 === 1 ? 'reminder' : 'none');
} catch (e) {}

// order_data_received приходит уже с order_name/order_color/order_price от E2a (та же staticData-запись,
// что мы сохранили выше при order_confirmed) — досчитываем order_summary, если он ещё не собран.
if (!orderSummary && branch === 'order_data_received') {
  const parts = [src.order_name, src.order_color, (src.order_price !== '' && src.order_price != null ? src.order_price + ' евро' : '')].filter(Boolean);
  orderSummary = parts.join(', ');
  // E11: сопутствующий товар виден оператору в той же строке, что и основной товар.
  if (src.accessory_name) {
    orderSummary += ` + ${src.accessory_name} (${src.accessory_price} евро)`;
  }
}

// G0: номер заказа (NW-<id> из E3b) — FAQ уже обещает клиенту «уточнить статус по номеру» —
// назвать его голосом обязательно при order_data_received, иначе обещание без функции.
if (branch === 'order_data_received' && src.order_number) {
  answerFactsOverride = (src.answer_facts || '') + ` Номер заказа: ${src.order_number}. Обязательно назови его в ответе, например «ваш заказ ${src.order_number} принят».`;
}

return [{ json: {
  branch,
  answer_facts: answerFactsOverride || src.answer_facts || src.context || '',
  source_text: clientText,
  lang,
  escalate: orderConfirmed || src.escalate === true,
  attempts: src.attempts || 0,
  guardrail: src.guardrail || '',
  chat_id: chatId,
  client_name: clientName,
  client_username: clientUsername,
  order_summary: orderSummary,
  delivery_method: src.delivery_method || '',
  address: src.address || '',
  email: src.email || '',
  first_name: src.first_name || '',
  last_name: src.last_name || '',
  phone: src.phone || '',
  order_number: src.order_number || '',
  accessory_name: src.accessory_name || '',
  accessory_price: src.accessory_price !== undefined ? src.accessory_price : '',
  disclaimerVariant
}, pairedItem: { item: 0 } }];

// Строка журнала обращений для листа «Черновик».
// Ответ берём из ноды 14 (что реально озвучено), остальное — из единой точки ответа.
// Ссылка на ноду 13 здесь надёжна: тот же приём уже работает в ноде 15 (TTS),
// но всё равно в try/catch — выражения со сквозными ссылками падают тихо.
const spoken = String($json.text || '');

let j = {};
try { j = $('13. Единая точка ответа').first().json || {}; } catch (e) {}

// [PII] телефоны маскируем и в вопросе, и в ответе — как в ноде 17
const redact = (s) => String(s || '').replace(/\+?\d[\d\s\-()]{6,}\d/g, '[PHONE]');

// Человеческое название ветки: лист читает человек, а не машина
const TYPE = {
  stock: 'Склад',
  faq: 'FAQ',
  none: 'Отказ (не по теме)',
  repeat: 'Просьба повторить',
  escalate: 'Эскалация к оператору'
};

const ts = new Date().toISOString().slice(0, 19).replace('T', ' ');

return [{ json: {
  'Дата': ts,
  'Chat ID': String(j.chat_id || 'unknown'),
  'Имя': String(j.client_name || ''),
  'Тип': TYPE[j.branch] || String(j.branch || 'unknown'),
  'Вопрос': redact(j.source_text),
  'Ответ': redact(spoken)
}, pairedItem: { item: 0 } }];

