// Аудио для запасного (облачного) распознавания.
// Error-выход HTTP-ноды бинарные данные не передаёт (прогон 929),
// поэтому берём файл у той ноды, где он точно есть.
let binary = {};
try {
  binary = $('4. Telegram Get File (audio)').first().binary || {};
} catch (e) {}

if (!binary || !binary.data) {
  // Нечем распознавать — пусть облачная нода честно упадёт в ветку «повторите»,
  // а не молча оборвётся.
  return [{ json: { stt_fallback: 'audio_missing' }, pairedItem: { item: 0 } }];
}

return [{ json: { stt_fallback: 'cloud' }, binary, pairedItem: { item: 0 } }];

// Жалоба клиента — согласно матрице рисков (протокол §2.0) всегда передаётся оператору,
// а не отсекается как оффтоп. Закрыто расхождение §8.0 (прогон 906: жалоба получила отказ).
const j = $input.first().json;
return [{
  json: {
    branch: 'complaint',
    escalate: true,
    source_text: j.source_text || '',
    answer_facts: 'Клиент высказал жалобу или претензию. Скажи спокойно, что обращение принято и передано живому оператору, который свяжется с клиентом и разберётся в ситуации.'
  },
  pairedItem: { item: 0 }
}];

