parameters.jsCode:
// G0: E3 вставила заказ с RETURNING id — собираем клиентский номер NW-<id> и возвращаем все исходные
// поля из E2a (выход E3 содержит ТОЛЬКО id — всё остальное нужно 13/20/E4).
// Если INSERT упал (onError: continueRegularOutput на E3) — id не придёт, номер останется пустым (грациозная деградация вместо падения всей ветки).
let id = null;
try { id = $input.first().json.id; } catch (e) {}

let src = {};
try { src = $('E2a. Обработка текста при ожидании формы заказа').first().json; } catch (e) {}

const order_number = id != null ? ('NW-' + id) : '';

return [{ json: Object.assign({}, src, { order_id: id, order_number }), pairedItem: { item: 0 } }];

