  let j = {};
  try { j = $('13. Единая точка ответа').first().json || {}; } catch (e) {}
  let baseName = '', baseColor = '', base = null;
  try {
    const e2 = $('E2a. Обработка текста при ожидании формы заказа').first().json;
    baseName = String(e2.order_name || '');
